  dcaScheduleExecutionsByScheduleId: DcaScheduleExecutionsConnection;
  /** Reads and enables pagination through a set of `DcaScheduleOrderRouteHop`. */
  dcaScheduleOrderRouteHopsByScheduleId: DcaScheduleOrderRouteHopsConnection;
  /** Reads a single `Event` that is related to this `DcaSchedule`. */
