  eventId?: Maybe<Scalars['String']['output']>;
  id: Scalars['String']['output'];
  maxAmountIn?: Maybe<Scalars['BigFloat']['output']>;
  maxRetries?: Maybe<Scalars['Int']['output']>;
  minAmountOut?: Maybe<Scalars['BigFloat']['output']>;
  operationId?: Maybe<Scalars['String']['output']>;
  orderType: Scalars['String']['output'];
  /** Reads a single `Account` that is related to this `DcaSchedule`. */
