  ownerId?: Maybe<Scalars['String']['output']>;
  paraBlockHeight: Scalars['Int']['output'];
  period?: Maybe<Scalars['Int']['output']>;
  relayBlockHeight: Scalars['Int']['output'];
  slippage?: Maybe<Scalars['Int']['output']>;
  stabilityThreshold?: Maybe<Scalars['Int']['output']>;
  startExecutionBlock?: Maybe<Scalars['Int']['output']>;
  status?: Maybe<Scalars['String']['output']>;
  totalAmount?: Maybe<Scalars['BigFloat']['output']>;
  totalExecutedAmountIn?: Maybe<Scalars['BigFloat']['output']>;
  totalExecutedAmountOut?: Maybe<Scalars['BigFloat']['output']>;
  traceIds?: Maybe<Array<Maybe<Scalars['String']['output']>>>;
