export type GetLbppoolHistoricalDataQueryVariables = Exact<{
  filter?: InputMaybe<LbppoolHistoricalDatumFilter>;
}>;


export type GetLbppoolHistoricalDataQuery = { __typename?: 'Query', lbppoolHistoricalData?: { __typename?: 'LbppoolHistoricalDataConnection', nodes: Array<{ __typename?: 'LbppoolHistoricalDatum', startBlockNumber?: number | null, endBlockNumber?: number | null, initialWeight: number, finalWeight: number, feeCollectorId?: string | null, fee: Array<number | null>, repayTarget: any, weightCurve: string, poolId?: string | null, assetAId?: string | null, assetBId?: string | null, assetABalance: any, assetBBalance: any, paraBlockHeight: number } | null> } | null };

export type GetXykpoolHistoricalDataQueryVariables = Exact<{
  filter?: InputMaybe<XykpoolHistoricalDatumFilter>;
}>;


export type GetXykpoolHistoricalDataQuery = { __typename?: 'Query', xykpoolHistoricalData?: { __typename?: 'XykpoolHistoricalDataConnection', nodes: Array<{ __typename?: 'XykpoolHistoricalDatum', assetABalance: any, assetAId?: string | null, assetBBalance: any, assetBId?: string | null, poolId?: string | null, paraBlockHeight: number } | null> } | null };

export type GetXykpoolSwapsDataQueryVariables = Exact<{
  filter?: InputMaybe<SwapFilter>;
}>;


export type GetXykpoolSwapsDataQuery = { __typename?: 'Query', swaps?: { __typename?: 'SwapsConnection', nodes: Array<{ __typename?: 'Swap', swapperId?: string | null, fillerId?: string | null, fillerType: string, swapFees: { __typename?: 'SwapFeesConnection', nodes: Array<{ __typename?: 'SwapFee', amount: any, recipientId?: string | null, asset?: { __typename?: 'Asset', id: string } | null } | null> }, swapInputs: { __typename?: 'SwapInputRecordsConnection', nodes: Array<{ __typename?: 'SwapInputRecord', amount?: any | null, asset?: { __typename?: 'Asset', id: string } | null } | null> }, swapOutputs: { __typename?: 'SwapOutputsConnection', nodes: Array<{ __typename?: 'SwapOutput', amount?: any | null, asset?: { __typename?: 'Asset', id: string } | null } | null> } } | null> } | null };


export const GetLbppoolHistoricalData = gql`
    query GetLbppoolHistoricalData($filter: LbppoolHistoricalDatumFilter) {
  lbppoolHistoricalData(filter: $filter) {
    nodes {
      startBlockNumber
      endBlockNumber
      initialWeight
      finalWeight
      feeCollectorId
      fee
      repayTarget
      weightCurve
      poolId
      assetAId
      assetBId
      assetABalance
      assetBBalance
      paraBlockHeight
    }
  }
}
    `;
export const GetXykpoolHistoricalData = gql`
    query GetXykpoolHistoricalData($filter: XykpoolHistoricalDatumFilter) {
  xykpoolHistoricalData(filter: $filter) {
    nodes {
      assetABalance
      assetAId
      assetBBalance
      assetBId
      poolId
      paraBlockHeight
    }
  }
}
    `;
export const GetXykpoolSwapsData = gql`
    query GetXykpoolSwapsData($filter: SwapFilter) {
  swaps(filter: $filter) {
    nodes {
      swapperId
      fillerId
      fillerType
      swapFees {
        nodes {
          amount
          asset {
            id
          }
          recipientId
        }
      }
      swapInputs {
        nodes {
          amount
          asset {
            id
          }
        }
      }
      swapOutputs {
        nodes {
          amount
          asset {
            id
          }
        }
      }
    }
  }
}
    `;